const e = $input.first().json;
const msg = String((e.execution && e.execution.error && e.execution.error.message) || '');
const expected = [/publishing time must be in the future/i,/already been published/i,/already published/i,/no post found/i,/cannot schedule from status/i,/post not found/i,/draft not found/i,/not found in (the )?(draft|queue)/i,/invalid status/i,/status must be/i,/cannot (publish|approve|edit) .*status/i];
if (expected.some(r => r.test(msg))) { return []; }
const wfId = e.workflow && e.workflow.id;
const exId = e.execution && e.execution.id;
const base = 'https://n8n.example.com';
const link = exId ? (e.execution.url || (base + '/workflow/' + wfId + '/executions/' + exId)) : '(no execution id - manual/test run)';
const stack = String((e.execution && e.execution.error && e.execution.error.stack) || '').split('\n').slice(0,8).join('\n');
const body = ['Workflow: ' + (e.workflow && e.workflow.name),'Workflow ID: ' + wfId,'Execution ID: ' + exId,'Execution link: ' + link,'Mode: ' + (e.execution && e.execution.mode),'Last node: ' + (e.execution && e.execution.lastNodeExecuted),'','Error message: ' + msg,'','Stack (excerpt):',stack].join('\n');
return [{json:{subject:'[n8n] Error in ' + (e.workflow && e.workflow.name), body}}];
